CREATE TABLE IF NOT EXISTS shop_account_appeal(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(40) NOT NULL,member_id BIGINT NULL,contact VARCHAR(200) NOT NULL,evidence VARCHAR(2000) NOT NULL,access_hash VARCHAR(64) NOT NULL UNIQUE,new_password_hash VARCHAR(100) NOT NULL,original_password_hash VARCHAR(100) NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',note VARCHAR(1500) NOT NULL DEFAULT '',reviewer VARCHAR(64) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
